{
  "units": [
    {
      "quote": "8 FAM 403.1-4 Material Discrepancies (Major name changes)\n\n(CT:CITZ-141; 03-10-2026)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Provides the section title and administrative amendment metadata (CT:CITZ-141; 03-10-2026), conveying no operational rule or requirement."
    },
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "Defines a material discrepancy as any name change not categorized as immaterial under 8 FAM 403.1-5."
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The applicant is obligated to provide an explanation for any material discrepancy found between the name entered on the application and the name shown in the citizenship/nationality evidence and identity evidence."
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Except where an exception applies for married names under 8 FAM 403.1-4(C), applicants are required to document material discrepancies between the application name and citizenship/nationality or identity evidence by submitting one or more of the documents authorized in this section."
    },
    {
      "quote": "(1) Court orders or decrees:\n\n(a) Name change orders; or\n\n(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Court orders or decrees—specifically name change orders or divorce decrees—are acceptable documentation options for verifying a material name change."
    },
    {
      "quote": "(2) Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Certificates of naturalization are an acceptable means of documenting a material name change."
    },
    {
      "quote": "(3) Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Marriage certificates are an acceptable means of documenting a material name change."
    },
    {
      "quote": "(4) Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Documentation showing a legal name change effected by operation of state law is an acceptable means of documenting a material name change."
    },
    {
      "quote": "(5) Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Documentation demonstrating customary usage is an acceptable means of documenting a material name change."
    },
    {
      "quote": "Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Personnel are mandatory required to inspect and review all submitted evidence of material name changes for signs of alteration or counterfeiting."
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "An applicant is prohibited from continuing to use a previous name following a material name change unless that previous name's continued use is expressly permitted by the name change documentation."
    },
    {
      "quote": "The applicant's name is an integral part of her/his identity. Consequently, under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Affirms that name is central to identity and notes that, pursuant to 22 CFR 51.23(c) and Department guidance, evidence of identity may be required to establish the name that best identifies an applicant."
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "scope_quotes": [
        "Consequently, under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "requirement",
      "meaning": "When an applicant who underwent a material name change over one year prior to applying on Form DS-11 has not updated their ID to the new name, the adjudicator is required to suspend the application and request acceptable ID displaying the new name."
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "scope_quotes": [
        "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ],
      "kind": "permission",
      "meaning": "Where an application would otherwise be suspended for an updated ID following a material name change over a year old, but urgent or emergency travel leaves insufficient time to obtain acceptable ID, adjudicators are permitted to issue a limited-validity passport in the requested name."
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "States the general expectation that an applicant will require their name change documentation in order to update the name on their identification."
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL);",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "When returning name change documentation to an applicant along with an information request letter (IRL), adjudicators must make complete notations on the documentation beforehand, explicitly indicating that it was 'seen and returned.'"
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "Applicants whose material name change took place within one year prior to submitting Form DS-11 are exempt from having to provide identification in their new name."
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "scope_quotes": [
        "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ],
      "kind": "requirement",
      "meaning": "Applicants applying on Form DS-11 within one year of a material name change whose ID has not yet been updated are required to submit their name change documentation."
    }
  ]
}

